// Controlled service state shares the connection and transaction with L1.
private controlledSchema(): void {
  this.db.exec(`CREATE TABLE IF NOT EXISTS vc_scopes(scope_key TEXT PRIMARY KEY, revision INTEGER NOT NULL DEFAULT 0);
    CREATE TABLE IF NOT EXISTS vc_operations(operation_id TEXT PRIMARY KEY, scope_key TEXT NOT NULL, receipt TEXT NOT NULL);`);
}
getScope(scopeKey: string): { revision: number } {
  this.controlledSchema();
  return this.db.prepare("SELECT revision FROM vc_scopes WHERE scope_key=?").get(scopeKey) as { revision: number } ?? { revision: 0 };
}
getOperation(operationId: string): any {
  this.controlledSchema();
  const row = this.db.prepare("SELECT receipt FROM vc_operations WHERE operation_id=?").get(operationId) as { receipt: string } | undefined;
  return row ? JSON.parse(row.receipt) : null;
}
commitPrepared(input: { operationId: string; scopeKey: string; revision: number; spaceId: string;
  filter: IsolationFilter; l0Records?: L0Record[]; targets: Array<{id: string; version: number}>;
  records: Array<{record: MemoryRecord; embedding: Float32Array}> }): any {
  this.controlledSchema();
  if (this.degraded || !this.ftsAvailable || !this.vecTablesReady) throw new Error("STORE_UNAVAILABLE");
  this.db.exec("BEGIN IMMEDIATE");
  try {
    const receipt = { operationId: input.operationId, scopeKey: input.scopeKey, revision: input.revision,
      spaceId: input.spaceId, recordIds: input.records.map(x => x.record.id), sourceIds: (input.l0Records ?? []).map(x => x.id), status: "committed" };
    const previous = this.getOperation(input.operationId);
    if (previous) {
      if (JSON.stringify(previous) !== JSON.stringify(receipt)) throw new Error("OPERATION_CONFLICT");
      this.db.exec("COMMIT"); return previous;
    }
    if (this.getScope(input.scopeKey).revision !== input.revision) throw new Error("STALE_REVISION");
    const space = this.getSpace();
    if (!space || space.spaceId !== input.spaceId || space.rebuilding) throw new Error("SPACE_NOT_READY");
    for (const target of input.targets) {
      const row = this.stmtGetMeta.get(target.id) as any;
      if (!row || row.version !== target.version || !rowMatchesIsolation(row, input.filter)) throw new Error("TARGET_VERSION_CONFLICT");
    }
    for (const {record, embedding} of input.records) {
      const row = { team_id: record.teamId, user_id: record.userId, agent_id: record.agentId,
        session_id: record.sessionId, session_key: record.sessionKey, task_id: record.taskId };
      if (!rowMatchesIsolation(row, input.filter) || this.stmtGetMeta.get(record.id)) throw new Error("RECORD_SCOPE_CONFLICT");
      if (embedding.length !== this.dimensions || !embedding.every(Number.isFinite) || embedding.every(v => v === 0)) throw new Error("EMBEDDING_INVALID");
    }
    for (const record of input.l0Records ?? []) {
      const identity = { team_id: record.teamId, user_id: record.userId, agent_id: record.agentId,
        session_id: record.sessionId, session_key: record.sessionKey, task_id: record.taskId };
      const existing = this.stmtL0GetMeta.get(record.id) as any;
      if (!rowMatchesIsolation(identity, input.filter) || (existing && (!rowMatchesIsolation(existing, input.filter) ||
        existing.message_text !== record.messageText || existing.timestamp !== record.timestamp))) throw new Error("SOURCE_CONFLICT");
      if (!this.upsertL0(record, undefined, true)) throw new Error("SOURCE_WRITE_FAILED");
    }
    for (const target of input.targets) this.deleteControlledRecord(target.id);
    for (const {record, embedding} of input.records) {
      if (!this.upsertL1(record, embedding, true)) throw new Error("COMMIT_FAILED");
    }
    this.db.prepare("INSERT INTO vc_operations VALUES(?,?,?)").run(input.operationId, input.scopeKey, JSON.stringify(receipt));
    this.db.exec("COMMIT"); return receipt;
  } catch (error) { this.db.exec("ROLLBACK"); throw error; }
}
invalidateScope(scopeKey: string): { revision: number } {
  this.controlledSchema();
  this.db.exec("BEGIN IMMEDIATE");
  try {
    this.db.prepare("INSERT INTO vc_scopes VALUES(?,1) ON CONFLICT(scope_key) DO UPDATE SET revision=revision+1").run(scopeKey);
    this.db.prepare("UPDATE vc_operations SET receipt=json_set(receipt,'$.status','revoked') WHERE scope_key=?").run(scopeKey);
    const result = this.getScope(scopeKey); this.db.exec("COMMIT"); return result;
  } catch (error) { this.db.exec("ROLLBACK"); throw error; }
}

